public class ConfusionMatrixTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String counts(ConfusionMatrix m) {
        return "tp=" + m.truePositives() + " fp=" + m.falsePositives()
                + " tn=" + m.trueNegatives() + " fn=" + m.falseNegatives();
    }

    public static void main(String[] args) {
        try {
            ConfusionMatrix m = new ConfusionMatrix(
                    new int[]{1, 1, 1, 1, 0, 0, 0, 0},
                    new int[]{1, 1, 0, 1, 1, 0, 0, 0});
            check("the four outcome counts", "tp=3 fp=1 tn=3 fn=1", counts(m));
            check("total()", 8, m.total());
            check("accuracy()", 0.75, m.accuracy());
            check("precision()", 0.75, m.precision());

            ConfusionMatrix never = new ConfusionMatrix(new int[]{1, 1, 0, 0}, new int[]{0, 0, 0, 0});
            check("a model that never flags anything", "tp=0 fp=0 tn=2 fn=2", counts(never));
            check("its precision falls back to 0.0", 0.0, never.precision());

            ConfusionMatrix empty = new ConfusionMatrix(new int[]{}, new int[]{});
            check("an empty dataset has accuracy 0.0", 0.0, empty.accuracy());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        String mismatch = "no exception";
        try {
            new ConfusionMatrix(new int[]{1, 0, 1}, new int[]{1, 0});
        } catch (IllegalArgumentException e) {
            mismatch = "IllegalArgumentException";
        } catch (RuntimeException e) {
            mismatch = e.getClass().getSimpleName();
        }
        check("mismatched lengths are rejected", "IllegalArgumentException", mismatch);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

