/**
 * Confusion-matrix counts for a binary classifier, plus accuracy and precision.
 */
public class ConfusionMatrix {

    private int truePositives;
    private int falsePositives;
    private int trueNegatives;
    private int falseNegatives;

    public ConfusionMatrix(int[] actual, int[] predicted) {
        if (actual == null || predicted == null || actual.length != predicted.length) {
            throw new IllegalArgumentException("actual and predicted must be the same length");
        }
        for (int i = 0; i < actual.length; i++) {
            if (actual[i] == 1 && predicted[i] == 1) {
                truePositives++;
            } else if (actual[i] == 0 && predicted[i] == 1) {
                falsePositives++;
            } else if (actual[i] == 0 && predicted[i] == 0) {
                trueNegatives++;
            } else {
                falseNegatives++;
            }
        }
    }

    public int truePositives() {
        return truePositives;
    }

    public int falsePositives() {
        return falsePositives;
    }

    public int trueNegatives() {
        return trueNegatives;
    }

    public int falseNegatives() {
        return falseNegatives;
    }

    public int total() {
        return truePositives + falsePositives + trueNegatives + falseNegatives;
    }

    public double accuracy() {
        int count = total();
        if (count == 0) {
            return 0.0;
        }
        return (double) (truePositives + trueNegatives) / count;
    }

    public double precision() {
        int flagged = truePositives + falsePositives;
        if (flagged == 0) {
            return 0.0;
        }
        return (double) truePositives / flagged;
    }
}
